/*
 * The leaderboard client.
 *
 * One idea worth stating, because all four games implemented it and it is not
 * obvious: the run id is generated by the CLIENT, before submission, and the API
 * upserts on it. That is what lets a player finish a run, see their score on the
 * board, then type a name and have the SAME row change name rather than a second
 * row appear. Renaming can never change the score — the server keeps the higher
 * of the two — so the id is not a trust boundary, only an identity.
 *
 * Failure is silent on purpose. A game that is offline still has its local best,
 * and an error toast about a leaderboard is noise at the exact moment the player
 * wants to see their score.
 */

const ENDPOINT = '/api/scores';

function newRunId() {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  // Old Safari. Length and alphabet must still satisfy the API's /^[a-z0-9-]{8,64}$/.
  return `run-${Date.now().toString(36)}-${Math.floor(Math.random() * 1e9).toString(36)}`;
}

/**
 * @param {string} game  the slug, which the API validates against its own list
 */
export function makeScoreboard(game) {
  let pending = null;

  const post = (name) => {
    if (!pending) return Promise.resolve(false);
    return fetch(ENDPOINT, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ ...pending, name }),
    })
      .then((r) => r.ok)
      .catch(() => false);
  };

  return {
    /**
     * Submit a finished run.
     * @param {{score:number, wave?:number, difficulty?:string}} result
     * @param {string} name  the player's current name
     */
    submit(result, name) {
      const score = Math.floor(Number(result.score) || 0);
      if (score <= 0) return Promise.resolve(false);
      pending = {
        id: newRunId(),
        game,
        score,
        // Whatever second number this game ranks by: waves, metres, rank, day.
        wave: Math.floor(Number(result.wave) || 0),
        difficulty: result.difficulty || 'veteran',
      };
      return post(name);
    },

    /** Re-submit the same run under a new name. Same id, so the row is updated. */
    rename(name) {
      return post(name);
    },

    /** Whether there is a run on the board that a rename would reach. */
    get hasRun() {
      return !!pending;
    },
  };
}

/** Read the board. Used by the arcade pages rather than by the games. */
export async function fetchScores(game, { period = 'week', limit = 10 } = {}) {
  try {
    const res = await fetch(`${ENDPOINT}?game=${encodeURIComponent(game)}&period=${period}&limit=${limit}`);
    if (!res.ok) return [];
    const body = await res.json();
    return body.scores || [];
  } catch {
    return [];
  }
}
